  llmModelId: varchar("llm_model_id").notNull(),
  systemPrompt: text("system_prompt").notNull(),
  maxTokens: integer("max_tokens").default(2048),
  temperature: integer("temperature").default(70), // stored as integer (0-200 for 0.0-2.0)
