// Conversation History Component
function ConversationHistory({ agentId }: { agentId: string }) {
  const [search, setSearch] = useState("");
  const [selectedConversationId, setSelectedConversationId] = useState<string | null>(null);
  const [isMessageViewerOpen, setIsMessageViewerOpen] = useState(false);

  const { data: conversationsData, isLoading: conversationsLoading } = useQuery<{
    conversations: Array<{
      id: string;
      title: string;
      contactId?: string;
      updatedAt: string;
      isActive: boolean;
    }>;
    total: number;
  }>({
    queryKey: ['/api/conversations', { agentId, search }],
    enabled: !!agentId,
  });

  const { data: messagesData, isLoading: messagesLoading } = useQuery<{
    messages: Array<{
      id: string;
      content: string;
      role: 'user' | 'assistant' | 'system';
      createdAt: string;
    }>;
    total: number;
  }>({
    queryKey: ['/api/conversations', selectedConversationId, 'messages'],
    enabled: !!selectedConversationId,
  });

  const handleConversationClick = (conversationId: string) => {
    setSelectedConversationId(conversationId);
    setIsMessageViewerOpen(true);
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h3 className="text-lg font-semibold">Conversation History</h3>
          <p className="text-sm text-muted-foreground">
            View and search through past conversations with this agent
          </p>
        </div>
      </div>

      {/* Search Input */}
      <div className="space-y-4">
        <div className="relative">
          <input
            type="text"
            placeholder="Search conversations..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="w-full px-3 py-2 border border-border rounded-md bg-background"
            data-testid="input-conversation-search"
          />
        </div>

        {/* Conversations List */}
        <div className="space-y-2">
          {conversationsLoading ? (
            <div className="space-y-2">
              {[...Array(5)].map((_, i) => (
                <div key={i} className="p-4 border border-border rounded-lg">
                  <Skeleton className="h-4 w-3/4 mb-2" />
                  <Skeleton className="h-3 w-1/2" />
                </div>
              ))}
            </div>
          ) : conversationsData?.conversations?.length ? (
            conversationsData.conversations.map((conversation) => (
              <div
                key={conversation.id}
                className="p-4 border border-border rounded-lg hover-elevate cursor-pointer"
                onClick={() => handleConversationClick(conversation.id)}
                data-testid={`conversation-item-${conversation.id}`}
              >
                <div className="flex items-center justify-between">
                  <div>
                    <h4 className="font-medium">{conversation.title || 'Untitled Conversation'}</h4>
                    <p className="text-sm text-muted-foreground">
                      {conversation.contactId && `Contact: ${conversation.contactId}`}
                    </p>
                  </div>
                  <div className="text-xs text-muted-foreground">
                    {new Date(conversation.updatedAt).toLocaleDateString()}
                  </div>
                </div>
              </div>
            ))
          ) : (
            <div className="text-center py-8">
              <MessageCircle className="h-12 w-12 mx-auto text-muted-foreground mb-4" />
              <h4 className="font-medium mb-2">No conversations yet</h4>
              <p className="text-sm text-muted-foreground">
                Conversations will appear here once visitors start chatting with your agent
              </p>
            </div>
          )}
        </div>
      </div>

      {/* Off-canvas Message Viewer using Sheet */}
      <Sheet open={isMessageViewerOpen} onOpenChange={setIsMessageViewerOpen}>
        <SheetContent side="right" className="w-full max-w-2xl p-0">
          <SheetHeader className="p-4 border-b border-border">
            <SheetTitle>
              {conversationsData?.conversations?.find((c) => c.id === selectedConversationId)?.title || 'Conversation'}
            </SheetTitle>
            <p className="text-sm text-muted-foreground">Message History</p>
          </SheetHeader>

          {/* Messages */}
          <div className="flex-1 overflow-y-auto p-4 space-y-4 h-[calc(100vh-120px)]">
            {messagesLoading ? (
              <div className="space-y-4">
                {[...Array(3)].map((_, i) => (
                  <div key={i} className="flex gap-3">
                    <Skeleton className="h-8 w-8 rounded-full" />
                    <div className="space-y-2 flex-1">
                      <Skeleton className="h-4 w-1/4" />
                      <Skeleton className="h-16 w-full" />
                    </div>
                  </div>
                ))}
              </div>
            ) : messagesData?.messages?.length ? (
              messagesData.messages.map((message) => (
                <div key={message.id} className="flex gap-3" data-testid={`message-row-${message.id}`}>
                  <div className={cn(
                    "h-8 w-8 rounded-full flex items-center justify-center text-sm font-medium",
                    message.role === 'user' ? 'bg-primary text-primary-foreground' : 'bg-muted'
                  )}>
                    {message.role === 'user' ? 'U' : 'A'}
                  </div>
                  <div className="flex-1 space-y-1">
                    <div className="flex items-center gap-2">
                      <span className="text-sm font-medium capitalize">{message.role}</span>
                      <span className="text-xs text-muted-foreground">
                        {new Date(message.createdAt).toLocaleTimeString()}
                      </span>
                    </div>
                    <div className={cn(
                      "p-3 rounded-lg text-sm",
                      message.role === 'user' 
                        ? 'bg-primary/10 text-primary-foreground border border-primary/20' 
                        : 'bg-muted'
                    )}
                    data-testid={`text-message-role-${message.role}-${message.id}`}
                    >
                      {message.content}
                    </div>
                  </div>
                </div>
              ))
            ) : (
              <div className="text-center py-8">
                <MessageSquare className="h-12 w-12 mx-auto text-muted-foreground mb-4" />
                <p className="text-sm text-muted-foreground">No messages in this conversation</p>
              </div>
            )}
          </div>
        </SheetContent>
      </Sheet>
    </div>
  );
}

client/src/pages/WorkflowStudio.tsx.content:
import { useState, useCallback, useRef, useEffect } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { 
  Workflow, 
  Play, 
  Square, 
  GitBranch, 
  Settings, 
  Plus, 
  Save, 
  ArrowLeft, 
  Download,
  Upload,
  Trash2,
  Copy,
  MousePointer2
} from "lucide-react";
import { useToast } from "@/hooks/use-toast";
import { cn } from "@/lib/utils";

interface WorkflowNode {
  id: string;
  type: 'start' | 'condition' | 'tool' | 'conversation' | 'end';
  position: { x: number; y: number };
  data: {
    label: string;
    description?: string;
    config?: Record<string, any>;
  };
}

interface WorkflowEdge {
  id: string;
  source: string;
  target: string;
  label?: string;
}

interface Workflow {
  id?: string;
  name: string;
  description: string;
  type: 'lead_qualification' | 'scheduler' | 'survey' | 'custom';
  nodes: WorkflowNode[];
  edges: WorkflowEdge[];
  isActive: boolean;
}

const nodeTypeConfig = {
  start: { 
    color: "bg-green-500", 
    label: "Start", 
    icon: Play,
    description: "Entry point for the workflow"
  },
  condition: { 
    color: "bg-blue-500", 
    label: "Condition", 
    icon: GitBranch,
    description: "Decision point based on user input"
  },
  tool: { 
    color: "bg-purple-500", 
    label: "Tool", 
    icon: Settings,
    description: "External API call or action"
  },
  conversation: { 
    color: "bg-orange-500", 
    label: "Message", 
    icon: Workflow,
    description: "Send a message to the user"
  },
  end: { 
    color: "bg-red-500", 
    label: "End", 
    icon: Square,
    description: "End point of the workflow"
  },
};

interface WorkflowStudioProps {
  workflowId?: string;
  onBack: () => void;
}

export function WorkflowStudio({ workflowId, onBack }: WorkflowStudioProps) {
  const { toast } = useToast();
  const queryClient = useQueryClient();
  const canvasRef = useRef<HTMLDivElement>(null);

  const [workflow, setWorkflow] = useState<Workflow>({
    name: "New Workflow",
    description: "",
    type: "custom",
    nodes: [
      {
        id: "start-1",
        type: "start",
        position: { x: 100, y: 200 },
        data: { label: "Start" }
      },
      {
        id: "end-1",
        type: "end",
        position: { x: 600, y: 200 },
        data: { label: "End" }
      }
    ],
    edges: [
      {
        id: "edge-1",
        source: "start-1",
        target: "end-1"
      }
    ],
    isActive: false,
  });

  const [selectedNode, setSelectedNode] = useState<WorkflowNode | null>(null);
  const [draggedNodeType, setDraggedNodeType] = useState<string | null>(null);
  const [isEditingName, setIsEditingName] = useState(false);

  // Load workflow if editing existing one
  const { data: existingWorkflow, isLoading } = useQuery({
    queryKey: ['/api/workflows', workflowId],
    enabled: !!workflowId,
  });

  useEffect(() => {
    if (existingWorkflow) {
      setWorkflow(existingWorkflow);
    }
  }, [existingWorkflow]);

  const saveWorkflowMutation = useMutation({
    mutationFn: async (workflowData: Workflow) => {
      const url = workflowId ? `/api/workflows/${workflowId}` : '/api/workflows';
      const method = workflowId ? 'PUT' : 'POST';

      const response = await fetch(url, {
        method,
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${localStorage.getItem('auth_token')}`,
        },
        body: JSON.stringify(workflowData),
      });

      if (!response.ok) {
        throw new Error('Failed to save workflow');
      }

      return response.json();
    },
    onSuccess: () => {
      toast({
        title: "Workflow saved!",
        description: "Your workflow has been saved successfully.",
      });
      queryClient.invalidateQueries({ queryKey: ['/api/workflows'] });
    },
    onError: () => {
      toast({
        title: "Save failed",
        description: "Failed to save the workflow. Please try again.",
        variant: "destructive",
      });
    },
  });

  const handleSave = () => {
    saveWorkflowMutation.mutate(workflow);
  };

  const handleAddNode = (type: keyof typeof nodeTypeConfig, position: { x: number; y: number }) => {
    const newNode: WorkflowNode = {
      id: `${type}-${Date.now()}`,
      type,
      position,
      data: {
        label: nodeTypeConfig[type].label,
        description: nodeTypeConfig[type].description,
      },
    };

    setWorkflow(prev => ({
      ...prev,
      nodes: [...prev.nodes, newNode],
    }));
  };

  const handleNodeDrag = (nodeId: string, newPosition: { x: number; y: number }) => {
    setWorkflow(prev => ({
      ...prev,
      nodes: prev.nodes.map(node =>
        node.id === nodeId ? { ...node, position: newPosition } : node
      ),
    }));
  };

  const handleDeleteNode = (nodeId: string) => {
    if (workflow.nodes.find(n => n.id === nodeId)?.type === 'start') {
      toast({
        title: "Cannot delete",
        description: "Start nodes cannot be deleted.",
        variant: "destructive",
      });
      return;
    }

    setWorkflow(prev => ({
      ...prev,
      nodes: prev.nodes.filter(node => node.id !== nodeId),
      edges: prev.edges.filter(edge => edge.source !== nodeId && edge.target !== nodeId),
    }));

    if (selectedNode?.id === nodeId) {
      setSelectedNode(null);
    }
  };

  const handleCanvasDrop = (e: React.DragEvent) => {
    e.preventDefault();
    if (!draggedNodeType || !canvasRef.current) return;

    const rect = canvasRef.current.getBoundingClientRect();
    const position = {
      x: e.clientX - rect.left - 75, // Center the node
      y: e.clientY - rect.top - 25,
    };

    handleAddNode(draggedNodeType as keyof typeof nodeTypeConfig, position);
    setDraggedNodeType(null);
  };

  const handleCanvasDragOver = (e: React.DragEvent) => {
    e.preventDefault();
  };

  if (isLoading) {
    return (
      <div className="h-full flex items-center justify-center">
        <div className="text-center">
          <Workflow className="h-16 w-16 mx-auto mb-4 text-muted-foreground animate-pulse" />
          <p className="text-muted-foreground">Loading workflow...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="h-full flex flex-col">
      {/* Header */}
      <div className="border-b border-border p-4 flex items-center justify-between bg-background">
        <div className="flex items-center gap-4">
          <Button 
            variant="ghost" 
            size="sm" 
            onClick={onBack}
            data-testid="button-back-to-workflows"
          >
            <ArrowLeft className="h-4 w-4 mr-2" />
            Back
          </Button>

          <div className="flex items-center gap-2">
            {isEditingName ? (
              <Input
                value={workflow.name}
                onChange={(e) => setWorkflow(prev => ({ ...prev, name: e.target.value }))}
                onBlur={() => setIsEditingName(false)}
                onKeyDown={(e) => e.key === 'Enter' && setIsEditingName(false)}
                className="text-xl font-bold"
                autoFocus
              />
            ) : (
              <h1 
                className="text-xl font-bold cursor-pointer hover:bg-muted rounded px-2 py-1"
                onClick={() => setIsEditingName(true)}
                data-testid="text-workflow-name"
              >
                {workflow.name}
              </h1>
            )}
            <Badge variant="outline">{workflow.type}</Badge>
          </div>
        </div>

        <div className="flex items-center gap-2">
          <Button variant="outline" size="sm">
            <Download className="h-4 w-4 mr-2" />
            Export
          </Button>
          <Button variant="outline" size="sm">
            <Upload className="h-4 w-4 mr-2" />
            Import
          </Button>
          <Button 
            onClick={handleSave}
            disabled={saveWorkflowMutation.isPending}
            data-testid="button-save-workflow"
          >
            <Save className="h-4 w-4 mr-2" />
            {saveWorkflowMutation.isPending ? 'Saving...' : 'Save'}
          </Button>
        </div>
      </div>

      <div className="flex-1 flex">
        {/* Node Palette */}
        <div className="w-64 border-r border-border bg-muted/20 p-4 space-y-4">
          <h3 className="font-semibold text-sm text-muted-foreground uppercase tracking-wide">
            Node Types
          </h3>

          <div className="space-y-2">
            {Object.entries(nodeTypeConfig).map(([type, config]) => {
              const Icon = config.icon;
              return (
                <div
                  key={type}
                  className="flex items-center gap-3 p-3 rounded-lg border border-border bg-background cursor-grab hover:bg-muted/50 transition-colors"
                  draggable
                  onDragStart={() => setDraggedNodeType(type)}
                  data-testid={`node-type-${type}`}
                >
                  <div className={cn("w-3 h-3 rounded-full", config.color)} />
                  <Icon className="h-4 w-4" />
                  <div className="flex-1">
                    <div className="font-medium text-sm">{config.label}</div>
                    <div className="text-xs text-muted-foreground">{config.description}</div>
                  </div>
                </div>
              );
            })}
          </div>

          <div className="pt-4 border-t border-border">
            <h4 className="font-semibold text-sm mb-2">Instructions</h4>
            <p className="text-xs text-muted-foreground">
              Drag node types from above onto the canvas to build your workflow.
            </p>
          </div>
        </div>

        {/* Canvas */}
        <div className="flex-1 relative overflow-hidden">
          <div
            ref={canvasRef}
            className="w-full h-full bg-background relative"
            onDrop={handleCanvasDrop}
            onDragOver={handleCanvasDragOver}
            data-testid="workflow-canvas"
          >
            {/* Grid background */}
            <div className="absolute inset-0 opacity-10">
              <svg width="100%" height="100%">
                <defs>
                  <pattern id="grid" width="20" height="20" patternUnits="userSpaceOnUse">
                    <circle cx="1" cy="1" r="0.5" fill="currentColor" />
                  </pattern>
                </defs>
                <rect width="100%" height="100%" fill="url(#grid)" />
              </svg>
            </div>

            {/* Edges */}
            <svg className="absolute inset-0 pointer-events-none">
              {workflow.edges.map((edge) => {
                const sourceNode = workflow.nodes.find(n => n.id === edge.source);
                const targetNode = workflow.nodes.find(n => n.id === edge.target);

                if (!sourceNode || !targetNode) return null;

                const sourceX = sourceNode.position.x + 75;
                const sourceY = sourceNode.position.y + 25;
                const targetX = targetNode.position.x + 75;
                const targetY = targetNode.position.y + 25;

                return (
                  <line
                    key={edge.id}
                    x1={sourceX}
                    y1={sourceY}
                    x2={targetX}
                    y2={targetY}
                    stroke="hsl(var(--border))"
                    strokeWidth="2"
                    markerEnd="url(#arrowhead)"
                  />
                );
              })}

              <defs>
                <marker
                  id="arrowhead"
                  markerWidth="10"
                  markerHeight="7"
                  refX="9"
                  refY="3.5"
                  orient="auto"
                >
                  <polygon
                    points="0 0, 10 3.5, 0 7"
                    fill="hsl(var(--border))"
                  />
                </marker>
              </defs>
            </svg>

            {/* Nodes */}
            {workflow.nodes.map((node) => {
              const config = nodeTypeConfig[node.type];
              const Icon = config.icon;
              const isSelected = selectedNode?.id === node.id;

              return (
                <div
                  key={node.id}
                  className={cn(
                    "absolute w-32 h-12 rounded-lg border-2 bg-background cursor-pointer transition-all hover:shadow-md",
                    isSelected ? "border-primary shadow-lg" : "border-border",
                    config.color.replace('bg-', 'border-l-4 border-l-')
                  )}
                  style={{
                    left: node.position.x,
                    top: node.position.y,
                  }}
                  onClick={() => setSelectedNode(node)}
                  data-testid={`workflow-node-${node.id}`}
                >
                  <div className="flex items-center justify-center h-full px-2">
                    <Icon className="h-4 w-4 mr-2" />
                    <span className="text-sm font-medium truncate">{node.data.label}</span>
                  </div>

                  {isSelected && (
                    <Button
                      variant="destructive"
                      size="sm"
                      className="absolute -top-2 -right-2 h-6 w-6 p-0"
                      onClick={(e) => {
                        e.stopPropagation();
                        handleDeleteNode(node.id);
                      }}
                    >
                      <Trash2 className="h-3 w-3" />
                    </Button>
                  )}
                </div>
              );
            })}

            {/* Drop Zone Hint */}
            {draggedNodeType && (
              <div className="absolute inset-0 bg-primary/5 border-2 border-dashed border-primary/30 flex items-center justify-center">
                <div className="text-center">
                  <MousePointer2 className="h-8 w-8 mx-auto mb-2 text-primary" />
                  <p className="text-sm text-primary">Drop to add {nodeTypeConfig[draggedNodeType as keyof typeof nodeTypeConfig]?.label} node</p>
                </div>
              </div>
            )}
          </div>
        </div>

        {/* Properties Panel */}
        {selectedNode && (
          <div className="w-80 border-l border-border bg-muted/20 p-4 space-y-4">
            <h3 className="font-semibold text-sm text-muted-foreground uppercase tracking-wide">
              Node Properties
            </h3>

            <Card>
              <CardHeader className="pb-3">
                <CardTitle className="text-base">{nodeTypeConfig[selectedNode.type].label} Node</CardTitle>
              </CardHeader>
              <CardContent className="space-y-4">
                <div>
                  <label className="text-sm font-medium">Label</label>
                  <Input
                    value={selectedNode.data.label}
                    onChange={(e) => {
                      const updatedNode = {
                        ...selectedNode,
                        data: { ...selectedNode.data, label: e.target.value }
                      };
                      setSelectedNode(updatedNode);
                      setWorkflow(prev => ({
                        ...prev,
                        nodes: prev.nodes.map(n => n.id === selectedNode.id ? updatedNode : n)
                      }));
                    }}
                    placeholder="Enter node label"
                  />
                </div>

                <div>
                  <label className="text-sm font-medium">Description</label>
                  <Textarea
                    value={selectedNode.data.description || ""}
                    onChange={(e) => {
                      const updatedNode = {
                        ...selectedNode,
                        data: { ...selectedNode.data, description: e.target.value }
                      };
                      setSelectedNode(updatedNode);
                      setWorkflow(prev => ({
                        ...prev,
                        nodes: prev.nodes.map(n => n.id === selectedNode.id ? updatedNode : n)
                      }));
                    }}
                    placeholder="Enter node description"
                    rows={3}
                  />
                </div>

                <div className="text-xs text-muted-foreground">
                  <strong>Position:</strong> x: {selectedNode.position.x}, y: {selectedNode.position.y}
                </div>
              </CardContent>
            </Card>
          </div>
        )}
      </div>
    </div>
  );
}

client/src/pages/WorkflowsPage.tsx.content:
import { useState } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { 
  Workflow, 
  Play, 
  Pause,
  Settings, 
  Plus, 
  MoreVertical,
  Edit,
  Trash2,
  Copy,
  FileText,
  Clock
} from "lucide-react";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { useToast } from "@/hooks/use-toast";
import { WorkflowStudio } from "./WorkflowStudio";
import { WorkflowBuilder } from "@/components/WorkflowBuilder";
import { mockWorkflowTemplates } from "@/lib/mock-data";
import { WorkflowTemplate } from "@/lib/types";
import { cn } from "@/lib/utils";

interface Workflow {
  id: string;
  name: string;
  description: string;
  type: 'lead_qualification' | 'scheduler' | 'survey' | 'custom';
  isActive: boolean;
  createdAt: string;
  updatedAt: string;
  nodes: any[];
  edges: any[];
}

type ViewMode = 'list' | 'templates' | 'studio';

export default function WorkflowsPage() {
  const { toast } = useToast();
  const queryClient = useQueryClient();

  const [viewMode, setViewMode] = useState<ViewMode>('list');
  const [selectedWorkflowId, setSelectedWorkflowId] = useState<string | null>(null);

  // Fetch workflows from API
  const { data: workflows = [], isLoading, error } = useQuery({
    queryKey: ['/api/workflows'],
  });

  const deleteWorkflowMutation = useMutation({
    mutationFn: async (workflowId: string) => {
      const response = await fetch(`/api/workflows/${workflowId}`, {
        method: 'DELETE',
        headers: {
          'Authorization': `Bearer ${localStorage.getItem('auth_token')}`,
        },
      });

      if (!response.ok) {
        throw new Error('Failed to delete workflow');
      }
    },
    onSuccess: () => {
      toast({
        title: "Workflow deleted",
        description: "The workflow has been deleted successfully.",
      });
      queryClient.invalidateQueries({ queryKey: ['/api/workflows'] });
    },
    onError: () => {
      toast({
        title: "Delete failed",
        description: "Failed to delete the workflow. Please try again.",
        variant: "destructive",
      });
    },
  });

  const toggleWorkflowMutation = useMutation({
    mutationFn: async ({ workflowId, isActive }: { workflowId: string; isActive: boolean }) => {
      const response = await fetch(`/api/workflows/${workflowId}/toggle`, {
        method: 'PATCH',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${localStorage.getItem('auth_token')}`,
        },
        body: JSON.stringify({ isActive }),
      });

      if (!response.ok) {
        throw new Error('Failed to toggle workflow');
      }

      return response.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['/api/workflows'] });
    },
  });

  const handleCreateNew = () => {
    setSelectedWorkflowId(null);
    setViewMode('studio');
  };

  const handleEditWorkflow = (workflowId: string) => {
    setSelectedWorkflowId(workflowId);
    setViewMode('studio');
  };

  const handleSelectTemplate = (template: WorkflowTemplate) => {
    // Create a new workflow from template
    setSelectedWorkflowId(null);
    setViewMode('studio');
    // Pass template data to studio - would need to implement this
  };

  const handleBackToList = () => {
    setViewMode('list');
    setSelectedWorkflowId(null);
  };

  const getWorkflowTypeColor = (type: string) => {
    switch (type) {
      case 'lead_qualification': return 'bg-blue-100 text-blue-800 dark:bg-blue-900 dark:text-blue-200';
      case 'scheduler': return 'bg-green-100 text-green-800 dark:bg-green-900 dark:text-green-200';
      case 'survey': return 'bg-purple-100 text-purple-800 dark:bg-purple-900 dark:text-purple-200';
      case 'custom': return 'bg-gray-100 text-gray-800 dark:bg-gray-900 dark:text-gray-200';
      default: return 'bg-gray-100 text-gray-800 dark:bg-gray-900 dark:text-gray-200';
    }
  };

  if (viewMode === 'studio') {
    return (
      <WorkflowStudio 
        workflowId={selectedWorkflowId || undefined}
        onBack={handleBackToList}
      />
    );
  }

  if (viewMode === 'templates') {
    return (
      <div className="h-full">
        <div className="border-b border-border p-6">
          <div className="flex items-center justify-between">
            <div>
              <h1 className="text-2xl font-bold">Workflow Templates</h1>
              <p className="text-muted-foreground">
                Choose from pre-built templates to get started quickly
              </p>
            </div>
            <Button 
              variant="outline" 
              onClick={() => setViewMode('list')}
              data-testid="button-back-to-list"
            >
              Back to Workflows
            </Button>
          </div>
        </div>

        <div className="p-6">
          <WorkflowBuilder 
            templates={mockWorkflowTemplates}
            onSelectTemplate={handleSelectTemplate}
          />
        </div>
      </div>
    );
  }

  return (
    <div className="h-full flex flex-col">
      {/* Header */}
      <div className="border-b border-border p-6">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-2xl font-bold">Workflows</h1>
            <p className="text-muted-foreground">
              Design and manage conversation flows for your AI agents
            </p>
          </div>
          <div className="flex items-center gap-2">
            <Button 
              variant="outline"
              onClick={() => setViewMode('templates')}
              data-testid="button-browse-templates"
            >
              <FileText className="h-4 w-4 mr-2" />
              Browse Templates
            </Button>
            <Button 
              onClick={handleCreateNew}
              data-testid="button-create-workflow"
            >
              <Plus className="h-4 w-4 mr-2" />
              Create Workflow
            </Button>
          </div>
        </div>
      </div>

      {/* Content */}
      <div className="flex-1 p-6">
        {isLoading ? (
          <div className="text-center py-12">
            <Workflow className="h-16 w-16 mx-auto mb-4 text-muted-foreground animate-pulse" />
            <p className="text-muted-foreground">Loading workflows...</p>
          </div>
        ) : error ? (
          <div className="text-center py-12">
            <div className="text-center">
              <Workflow className="h-16 w-16 mx-auto text-destructive mb-4" />
              <h3 className="text-lg font-semibold mb-2">Failed to load workflows</h3>
              <p className="text-muted-foreground mb-4">
                Something went wrong while loading your workflows.
              </p>
              <Button onClick={() => queryClient.invalidateQueries({ queryKey: ['/api/workflows'] })}>
                Try Again
              </Button>
            </div>
          </div>
        ) : workflows.length === 0 ? (
          <div className="text-center py-12">
            <Workflow className="h-16 w-16 mx-auto text-muted-foreground mb-4" />
            <h3 className="text-lg font-semibold mb-2">No workflows yet</h3>
            <p className="text-muted-foreground mb-4">
              Create your first workflow to get started.
            </p>
            <div className="flex justify-center gap-2">
              <Button onClick={handleCreateNew}>
                <Plus className="h-4 w-4 mr-2" />
                Create Workflow
              </Button>
              <Button 
                variant="outline"
                onClick={() => setViewMode('templates')}
              >
                <FileText className="h-4 w-4 mr-2" />
                Browse Templates
              </Button>
            </div>
          </div>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {workflows.map((workflow: Workflow) => (
              <Card 
                key={workflow.id} 
                className="hover-elevate cursor-pointer group"
                data-testid={`workflow-card-${workflow.id}`}
              >
                <CardHeader className="pb-3">
                  <div className="flex items-center justify-between">
                    <div className="flex items-center gap-2">
                      <div className={cn(
                        "w-2 h-2 rounded-full",
                        workflow.isActive ? "bg-green-500" : "bg-gray-400"
                      )} />
                      <Badge 
                        variant="secondary" 
                        className={getWorkflowTypeColor(workflow.type)}
                      >
                        {workflow.type.replace('_', ' ')}
                      </Badge>
                    </div>

                    <DropdownMenu>
                      <DropdownMenuTrigger asChild>
                        <Button 
                          variant="ghost" 
                          size="sm"
                          className="opacity-0 group-hover:opacity-100 transition-opacity"
                          data-testid={`workflow-menu-${workflow.id}`}
                        >
                          <MoreVertical className="h-4 w-4" />
                        </Button>
                      </DropdownMenuTrigger>
                      <DropdownMenuContent align="end">
                        <DropdownMenuItem 
                          onClick={() => handleEditWorkflow(workflow.id)}
                          data-testid={`workflow-edit-${workflow.id}`}
                        >
                          <Edit className="h-4 w-4 mr-2" />
                          Edit
                        </DropdownMenuItem>
                        <DropdownMenuItem 
                          onClick={() => {/* Copy workflow */}}
                        >
                          <Copy className="h-4 w-4 mr-2" />
                          Duplicate
                        </DropdownMenuItem>
                        <DropdownMenuItem 
                          onClick={() => toggleWorkflowMutation.mutate({
                            workflowId: workflow.id,
                            isActive: !workflow.isActive
                          })}
                          data-testid={`workflow-toggle-${workflow.id}`}
                        >
                          {workflow.isActive ? (
                            <>
                              <Pause className="h-4 w-4 mr-2" />
                              Deactivate
                            </>
                          ) : (
                            <>
                              <Play className="h-4 w-4 mr-2" />
                              Activate
                            </>
                          )}
                        </DropdownMenuItem>
                        <DropdownMenuSeparator />
                        <DropdownMenuItem 
                          onClick={() => deleteWorkflowMutation.mutate(workflow.id)}
                          className="text-destructive"
                          data-testid={`workflow-delete-${workflow.id}`}
                        >
                          <Trash2 className="h-4 w-4 mr-2" />
                          Delete
                        </DropdownMenuItem>
                      </DropdownMenuContent>
                    </DropdownMenu>
                  </div>

                  <CardTitle 
                    className="text-lg leading-snug cursor-pointer"
                    onClick={() => handleEditWorkflow(workflow.id)}
                  >
                    {workflow.name}
                  </CardTitle>
                </CardHeader>

                <CardContent>
                  <p className="text-sm text-muted-foreground mb-4 line-clamp-2">
                    {workflow.description || "No description provided"}
                  </p>

                  <div className="flex items-center justify-between text-xs text-muted-foreground">
                    <div className="flex items-center gap-1">
                      <Clock className="h-3 w-3" />
                      <span>
                        Updated {new Date(workflow.updatedAt).toLocaleDateString()}
                      </span>
                    </div>
                    <div className="flex items-center gap-1">
                      <span>{workflow.nodes?.length || 0} nodes</span>
                    </div>
                  </div>
                </CardContent>
              </Card>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

client/src/components/CreateAgentModal.t.content:
import { useState } from "react";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { z } from "zod";
import { useMutation } from "@tanstack/react-query";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import {
  Form,
  FormControl,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from "@/components/ui/form";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Loader2, Copy, Check } from "lucide-react";
import { useToast } from "@/hooks/use-toast";
import { apiRequest, queryClient } from "@/lib/queryClient";

const createAgentSchema = z.object({
  name: z.string().min(1, "Name is required").max(100, "Name must be less than 100 characters"),
  description: z.string().min(1, "Description is required").max(500, "Description must be less than 500 characters"),
});

type CreateAgentForm = z.infer<typeof createAgentSchema>;

interface CreateAgentModalProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
}

export function CreateAgentModal({ open, onOpenChange }: CreateAgentModalProps) {
  const { toast } = useToast();
  const [createdAgentId, setCreatedAgentId] = useState<string | null>(null);
  const [copiedId, setCopiedId] = useState(false);

  const form = useForm<CreateAgentForm>({
    resolver: zodResolver(createAgentSchema),
    defaultValues: {
      name: "",
      description: "",
    },
  });

  const createAgentMutation = useMutation({
    mutationFn: async (data: CreateAgentForm) => {
      const response = await apiRequest("POST", "/api/agents", {
        ...data,
        type: "single_prompt", // Fixed type for Single Prompt Agents
      });
      return response.json();
    },
    onSuccess: (data) => {
      queryClient.invalidateQueries({ queryKey: ["/api/agents"] });
      setCreatedAgentId(data.id);
      toast({
        title: "Agent created successfully!",
        description: `${form.getValues("name")} has been created with ID: ${data.id}`,
      });
      form.reset();
    },
    onError: (error) => {
      toast({
        title: "Error creating agent",
        description: error instanceof Error ? error.message : "Failed to create agent. Please try again.",
        variant: "destructive",
      });
    },
  });

  const handleCopyId = async () => {
    if (createdAgentId) {
      try {
        await navigator.clipboard.writeText(createdAgentId);
        setCopiedId(true);
        setTimeout(() => setCopiedId(false), 2000);
        toast({
          title: "Copied!",
          description: "Agent ID copied to clipboard",
        });
      } catch (err) {
        toast({
          title: "Failed to copy",
          description: "Could not copy agent ID to clipboard",
          variant: "destructive",
        });
      }
    }
  };

  const onSubmit = async (data: CreateAgentForm) => {
    createAgentMutation.mutate(data);
  };

  const handleClose = () => {
    setCreatedAgentId(null);
    setCopiedId(false);
    form.reset();
    onOpenChange(false);
  };

  return (
    <Dialog open={open} onOpenChange={handleClose}>
      <DialogContent className="sm:max-w-[425px]">
        <DialogHeader>
          <DialogTitle data-testid="text-modal-title">Create Single Prompt Agent</DialogTitle>
          <DialogDescription>
            Create a new AI agent that responds with a single prompt. Fill in the details below to get started.
          </DialogDescription>
        </DialogHeader>

        {createdAgentId ? (
          <div className="space-y-4">
            <div className="text-center space-y-2">
              <div className="text-green-600 font-medium">✓ Agent Created Successfully!</div>
              <div className="text-sm text-muted-foreground">
                Your agent "{form.getValues("name")}" has been created.
              </div>
            </div>
            <div className="space-y-2">
              <label className="text-sm font-medium">Agent ID</label>
              <div className="flex items-center space-x-2">
                <Input
                  value={createdAgentId}
                  readOnly
                  className="font-mono text-sm"
                  data-testid="text-agent-id"
                />
                <Button
                  size="sm"
                  variant="outline"
                  onClick={handleCopyId}
                  data-testid="button-copy-id"
                >
                  {copiedId ? (
                    <Check className="h-4 w-4" />
                  ) : (
                    <Copy className="h-4 w-4" />
                  )}
                </Button>
              </div>
            </div>
          </div>
        ) : (
          <Form {...form}>
            <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-4">
              <FormField
                control={form.control}
                name="name"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>Agent Name</FormLabel>
                    <FormControl>
                      <Input
                        placeholder="Enter agent name..."
                        data-testid="input-agent-name"
                        {...field}
                      />
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />

              <FormField
                control={form.control}
                name="description"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>Description</FormLabel>
                    <FormControl>
                      <Textarea
                        placeholder="Describe what this agent does..."
                        className="min-h-[100px]"
                        data-testid="input-agent-description"
                        {...field}
                      />
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />
            </form>
          </Form>
        )}

        <DialogFooter>
          {createdAgentId ? (
            <Button onClick={handleClose} data-testid="button-close-modal">
              Close
            </Button>
          ) : (
            <>
              <Button
                variant="outline"
                onClick={handleClose}
                data-testid="button-cancel-create"
              >
                Cancel
              </Button>
              <Button
                type="submit"
                onClick={form.handleSubmit(onSubmit)}
                disabled={createAgentMutation.isPending}
                data-testid="button-submit-create"
              >
                {createAgentMutation.isPending ? (
                  <>
                    <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                    Creating...
                  </>
                ) : (
                  "Create Agent"
                )}
              </Button>
            </>
          )}
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

public/chat-widget.js.content:
/**
 * EchoAgent Chat Widget
 * A lightweight, embeddable chat widget that can be added to any website.
 * 
 * Usage:
 * <script 
 *   src="https://your-domain.com/chat-widget.js" 
 *   data-agent-id="YOUR_AGENT_ID">
 * </script>
 */

(function() {
  // Configuration - Update this to match your deployment
  const API_BASE_URL = window.location.origin + '/api';

  // Get agent ID from script tag
  const currentScript = document.currentScript;
  const agentId = currentScript.getAttribute('data-agent-id');

  if (!agentId) {
    console.error('EchoAgent Chat: Missing agent ID. Add data-agent-id attribute to the script tag.');
    return;
  }

  // Widget state
  let state = {
    isOpen: false,
    isContactInfoSubmitted: false,
    contactId: null,
    conversationId: null,
    messages: [],
    agentConfig: null,
    isLoading: false,
    // Voice call state
    isVoiceMode: false,
    voiceCall: null,
    isRecording: false,
    isProcessing: false,
    isPlaying: false,
    mediaRecorder: null,
    recordedChunks: [],
    websocket: null,
    roomId: null,
    callId: null
  };

  // API helper functions
  async function apiRequest(endpoint, options = {}) {
    const url = `${API_BASE_URL}${endpoint}`;
    const config = {
      headers: {
        'Content-Type': 'application/json',
        ...options.headers
      },
      ...options
    };

    if (config.body && typeof config.body === 'object') {
      config.body = JSON.stringify(config.body);
    }

    try {
      const response = await fetch(url, config);
      const data = await response.json();

      if (!response.ok) {
        throw new Error(data.error || `HTTP error! status: ${response.status}`);
      }

      return data;
    } catch (error) {
      console.error('API request failed:', error);
      throw error;
    }
  }

  // Load agent configuration
  async function loadAgentConfig() {
    try {
      const agentData = await apiRequest(`/widget/agents/${agentId}`);
      state.agentConfig = agentData;
      return agentData;
    } catch (error) {
      console.error('Failed to load agent configuration:', error);
      return null;
    }
  }

  // Create or get contact
  async function createContact(contactInfo) {
    try {
      const contact = await apiRequest(`/widget/agents/${agentId}/contacts`, {
        method: 'POST',
        body: contactInfo
      });
      state.contactId = contact.id;
      return contact;
    } catch (error) {
      console.error('Failed to create contact:', error);
      throw error;
    }
  }

  // Start conversation
  async function startConversation() {
    try {
      const conversation = await apiRequest(`/widget/agents/${agentId}/conversations`, {
        method: 'POST',
        body: {
          contactId: state.contactId,
          title: 'Widget Chat'
        }
      });
      state.conversationId = conversation.id;
      return conversation;
    } catch (error) {
      console.error('Failed to start conversation:', error);
      throw error;
    }
  }

  // Voice call functions
  async function startVoiceCall() {
    try {
      console.log('Starting voice call for agent:', agentId);

      // Start the voice call
      const callData = await apiRequest(`/widget/agents/${agentId}/voice/start`, {
        method: 'POST',
        body: {
          contactId: state.contactId,
          conversationId: state.conversationId
        }
      });

      console.log('Voice call started');
      state.voiceCall = callData;
      state.roomId = callData.roomId;
      state.callId = callData.callId;

      // Connect to WebSocket for real-time communication
      await connectToVoiceWebSocket(callData.token);

      return callData;
    } catch (error) {
      console.error('Failed to start voice call:', error);
      throw error;
    }
  }

  async function endVoiceCall() {
    try {
      if (state.callId) {
        console.log('Ending voice call:', state.callId);

        // Stop recording if active
        if (state.isRecording) {
          stopRecording();
        }

        // Close WebSocket connection
        if (state.websocket) {
          state.websocket.close();
          state.websocket = null;
        }

        // End the call on the backend
        await apiRequest(`/widget/agents/${agentId}/voice/end`, {
          method: 'POST',
          body: {
            callId: state.callId
          }
        });

        // Reset voice state
        state.voiceCall = null;
        state.callId = null;
        state.roomId = null;
        state.isVoiceMode = false;
        state.isRecording = false;
        state.isProcessing = false;
        state.isPlaying = false;

        console.log('Voice call ended successfully');
      }
    } catch (error) {
      console.error('Failed to end voice call:', error);
      throw error;
    }
  }

  // WebSocket connection for real-time voice communication
  async function connectToVoiceWebSocket(token) {
    try {
      // Include roomId, clientType (human), and callId in the WebSocket path
      const wsUrl = `${window.location.protocol === 'https:' ? 'wss:' : 'ws:'}//${window.location.host}/ws/${state.roomId}/human/${state.callId}`;
      console.log('Connecting to WebSocket:', wsUrl);

      // Create WebSocket connection with JWT token in protocol header
      state.websocket = new WebSocket(wsUrl, [`auth.${token}`]);

      state.websocket.onopen = () => {
        console.log('WebSocket connected for voice call');
      };

      state.websocket.onmessage = (event) => {
        try {
          const message = JSON.parse(event.data);
          handleVoiceWebSocketMessage(message);
        } catch (error) {
          console.error('Failed to parse WebSocket message:', error);
        }
      };

      state.websocket.onclose = (event) => {
        console.log('WebSocket connection closed:', event.code, event.reason);
        state.websocket = null;
      };

      state.websocket.onerror = (error) => {
        console.error('WebSocket error:', error);
      };

    } catch (error) {
      console.error('Failed to connect to voice WebSocket:', error);
      throw error;
    }
  }

  function handleVoiceWebSocketMessage(message) {
    console.log('Received WebSocket message:', message);

    switch (message.type) {
      case 'connected':
        console.log('WebSocket connection confirmed:', message);
        // Connection successful, ready to process audio
        break;

      case 'audio_response':
        // Play AI audio response
        if (message.audioData) {
          playAudioResponse(message.audioData);
        }
        break;

      case 'transcription':
        // Display user speech transcription
        if (message.text) {
          const container = document.querySelector('.echoagent-widget-container');
          const messagesContainer = container?.querySelector('.echoagent-chat-messages');
          if (messagesContainer) {
            addMessageToUI(message.text, 'user', messagesContainer);
          }
        }
        break;

      case 'ai_response':
        // Display AI text response
        if (message.text) {
          const container = document.querySelector('.echoagent-widget-container');
          const messagesContainer = container?.querySelector('.echoagent-chat-messages');
          if (messagesContainer) {
            addMessageToUI(message.text, 'bot', messagesContainer);
          }
        }
        break;

      case 'call_status':
        console.log('Call status update:', message.status);
        if (message.status === 'ended') {
          // Call ended by server, switch back to text mode
          const container = document.querySelector('.echoagent-widget-container');
          if (container) {
            const inputControls = container.querySelector('.echoagent-input-controls');
            const voiceControls = container.querySelector('.echoagent-voice-controls');
            const chatInput = container.querySelector('.echoagent-chat-input');

            if (inputControls && voiceControls && chatInput) {
              inputControls.style.display = 'flex';
              voiceControls.style.display = 'none';
              state.isVoiceMode = false;
              chatInput.focus();
            }
          }

          // Reset voice call state
          state.voiceCall = null;
          state.callId = null;
          state.roomId = null;
          state.isRecording = false;
          state.isProcessing = false;
          state.isPlaying = false;
        }
        break;

      case 'error':
        console.error('Voice WebSocket error:', message.message);
        showError('Voice call error: ' + message.message);
        break;

      default:
        console.warn('Unknown WebSocket message type:', message.type);
    }
  }

  // Audio recording functions
  async function startRecording() {
    try {
      console.log('Requesting microphone access...');

      // Request microphone access
      const stream = await navigator.mediaDevices.getUserMedia({ 
        audio: {
          sampleRate: 16000,
          channelCount: 1,
          echoCancellation: true,
          noiseSuppression: true
        } 
      });

      console.log('Microphone access granted');

      // Create MediaRecorder
      state.mediaRecorder = new MediaRecorder(stream, {
        mimeType: 'audio/webm'
      });

      state.recordedChunks = [];
      state.isRecording = true;

      // Handle data available
      state.mediaRecorder.ondataavailable = (event) => {
        if (event.data.size > 0) {
          state.recordedChunks.push(event.data);
        }
      };

      // Handle stop
      state.mediaRecorder.onstop = () => {
        console.log('Recording stopped');

        // Create audio blob
        const audioBlob = new Blob(state.recordedChunks, { type: 'audio/webm' });

        // Send audio data via WebSocket
        if (state.websocket && state.websocket.readyState === WebSocket.OPEN) {
          sendAudioToWebSocket(audioBlob);
        }

        // Stop microphone stream
        stream.getTracks().forEach(track => track.stop());

        state.isRecording = false;
        state.isProcessing = true;
        updateVoiceUI();
      };

      // Start recording
      state.mediaRecorder.start();
      console.log('Recording started');

      updateVoiceUI();

    } catch (error) {
      console.error('Failed to start recording:', error);
      showError('Could not access microphone. Please check your permissions.');
      state.isRecording = false;
      updateVoiceUI();
    }
  }

  function stopRecording() {
    if (state.mediaRecorder && state.isRecording) {
      console.log('Stopping recording...');
      state.mediaRecorder.stop();
    }
  }

  async function sendAudioToWebSocket(audioBlob) {
    try {
      console.log('Sending audio data to WebSocket, size:', audioBlob.size);

      // Convert blob to base64
      const reader = new FileReader();
      reader.onload = () => {
        const base64Audio = reader.result.split(',')[1]; // Remove data:audio/webm;base64, prefix

        const message = {
          type: 'audio_message',
          audioData: base64Audio,
          roomId: state.roomId,
          callId: state.callId
        };

        state.websocket.send(JSON.stringify(message));
        console.log('Audio message sent via WebSocket');
      };

      reader.readAsDataURL(audioBlob);

    } catch (error) {
      console.error('Failed to send audio to WebSocket:', error);
      state.isProcessing = false;
      updateVoiceUI();
    }
  }

  // Audio playback function
  function playAudioResponse(base64AudioData) {
    try {
      console.log('Playing AI audio response');
      state.isPlaying = true;
      updateVoiceUI();

      // Create audio element
      const audio = new Audio();
      audio.src = `data:audio/mpeg;base64,${base64AudioData}`;

      audio.onended = () => {
        console.log('Audio playback finished');
        state.isPlaying = false;
        state.isProcessing = false;
        updateVoiceUI();
      };

      audio.onerror = (error) => {
        console.error('Audio playback error:', error);
        state.isPlaying = false;
        state.isProcessing = false;
        updateVoiceUI();
      };

      audio.play().catch(error => {
        console.error('Failed to play audio:', error);
        state.isPlaying = false;
        state.isProcessing = false;
        updateVoiceUI();
      });

    } catch (error) {
      console.error('Failed to play audio response:', error);
      state.isPlaying = false;
      state.isProcessing = false;
      updateVoiceUI();
    }
  }

  // Send message
  async function sendMessage(content, role = 'user') {
    try {
      const message = await apiRequest(`/widget/conversations/${state.conversationId}/messages`, {
        method: 'POST',
        body: {
          content,
          role
        }
      });

      return message;
    } catch (error) {
      console.error('Failed to send message:', error);
      throw error;
    }
  }

  // Create widget DOM and styles
  function createWidgetDOM(agentConfig) {
    // Extract colors from agent preferences or use defaults
